const searchPlaces = `-- name: SearchPlaces :many
WITH RECURSIVE prefixed AS (
    SELECT p.id,
           (lower(p.name) = $2::text) AS is_exact,
           true AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           -- Folds to 0 without parent_ids, so path is not read
           -- (plan_cache_mode = force_custom_plan).
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    -- broad_first folds to a constant, so the plan keeps one of the two ways.
    WHERE NOT $4::boolean
      AND p.hidden_at IS NULL
      AND lower(p.name) LIKE $5::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      -- Below a parent: its id is on the place's path (places_path_idx).
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, is_exact DESC, level, len, lname, p.id
    LIMIT $7::integer
),
exact_named AS (
    SELECT p.id,
           true AS is_exact,
           true AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    WHERE $4::boolean
      AND p.hidden_at IS NULL
      AND lower(p.name) = $2::text
      AND lower(p.name) LIKE $5::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, level, len, lname, p.id
    LIMIT $7::integer
),
broad AS (
    SELECT p.id,
           false AS is_exact,
           true AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    WHERE $4::boolean
      AND p.hidden_at IS NULL
      AND p.kind IN ('PLACE_KIND_STATE', 'PLACE_KIND_CITY')
      AND lower(p.name) LIKE $5::text
      AND lower(p.name) <> $2::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, level, len, lname, p.id
    -- Nothing once the steps before fill the candidates: a LIMIT of 0
    -- returns before its scan starts (a WHERE filter would still start the
    -- parallel workers a large scan is planned with, some 3 to 8 ms).
    LIMIT CASE WHEN (SELECT count(*) FROM exact_named) < $7::integer
               THEN $7::integer ELSE 0 END
),
towns AS (
    SELECT p.id,
           false AS is_exact,
           true AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    WHERE $4::boolean
      AND p.hidden_at IS NULL
      AND p.kind = 'PLACE_KIND_TOWN'
      AND lower(p.name) LIKE $5::text
      AND lower(p.name) <> $2::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, level, len, lname, p.id
    LIMIT CASE WHEN (SELECT count(*) FROM exact_named) + (SELECT count(*) FROM broad) < $7::integer
               THEN $7::integer ELSE 0 END
),
venues AS (
    SELECT p.id,
           false AS is_exact,
           true AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    WHERE $4::boolean
      AND p.hidden_at IS NULL
      AND p.kind IN ('PLACE_KIND_MALL', 'PLACE_KIND_STORE')
      AND lower(p.name) LIKE $5::text
      AND lower(p.name) <> $2::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, level, len, lname, p.id
    LIMIT CASE WHEN (SELECT count(*) FROM exact_named) + (SELECT count(*) FROM broad)
                    + (SELECT count(*) FROM towns) < $7::integer
               THEN $7::integer ELSE 0 END
),
contained AS (
    SELECT p.id,
           false AS is_exact,
           false AS is_prefix,
           array_position(ARRAY['PLACE_KIND_STATE', 'PLACE_KIND_CITY', 'PLACE_KIND_TOWN',
                                'PLACE_KIND_MALL', 'PLACE_KIND_STORE']::text[], p.kind) AS level,
           CASE WHEN $3::uuid[] IS NULL THEN 0
                ELSE (SELECT min(array_position($3::uuid[], a)) FROM unnest(p.path) a)
           END AS under,
           char_length(p.name) AS len,
           lower(p.name) AS lname
    FROM places p
    WHERE NOT $4::boolean
      AND p.hidden_at IS NULL
      AND lower(p.name) LIKE $8::text
      AND lower(p.name) NOT LIKE $5::text
      AND ($6::text IS NULL OR p.kind = $6::text)
      AND ($3::uuid[] IS NULL
           OR (p.path && $3::uuid[] AND p.id <> ALL($3::uuid[])))
    ORDER BY under, level, len, lname, p.id
    -- With the candidates already full, no row is read (see broad).
    LIMIT CASE WHEN (SELECT count(*) FROM prefixed) < $7::integer
               THEN $7::integer ELSE 0 END
),
ranked AS (
    SELECT u.id, u.is_exact, u.is_prefix, u.level, u.under, u.len, u.lname FROM (SELECT id, is_exact, is_prefix, level, under, len, lname FROM prefixed UNION ALL SELECT id, is_exact, is_prefix, level, under, len, lname FROM exact_named
                     UNION ALL SELECT id, is_exact, is_prefix, level, under, len, lname FROM broad UNION ALL SELECT id, is_exact, is_prefix, level, under, len, lname FROM towns
                     UNION ALL SELECT id, is_exact, is_prefix, level, under, len, lname FROM venues UNION ALL SELECT id, is_exact, is_prefix, level, under, len, lname FROM contained) u
    ORDER BY u.under, u.is_exact DESC, u.is_prefix DESC, u.level, u.len, u.lname, u.id
    LIMIT $7::integer
),
candidates AS (
    SELECT r.under, r.is_exact, r.is_prefix, r.level, r.len, r.lname,
           p.id, p.kind, p.name, p.parent_id, p.timezone, p.source, p.user_added,
           coalesce(p.category, '') AS category
    FROM ranked r
    JOIN places p ON p.id = r.id
),
up AS (
    SELECT m.id AS place_id, m.parent_id AS ancestor_id, 1 AS depth
    FROM candidates m
    WHERE m.parent_id IS NOT NULL
    UNION ALL
    SELECT u.place_id, a.parent_id, u.depth + 1
    FROM up u
    JOIN places a ON a.id = u.ancestor_id
    WHERE a.parent_id IS NOT NULL AND u.depth < 8
)
SELECT m.id, m.kind, m.name, m.parent_id, m.timezone, m.source, m.user_added, m.category::text AS category,
       m.is_prefix, st.stories
FROM candidates m
CROSS JOIN LATERAL (
    SELECT count(*)::integer AS stories FROM (
        SELECT 1 FROM arcs a JOIN perspectives v ON v.arc_id = a.id
        WHERE a.place_path @> ARRAY[m.id]
          -- Stories under a hidden place are not readable, so not counted.
          AND NOT EXISTS (SELECT 1 FROM places h WHERE h.id = ANY(a.place_path) AND h.hidden_at IS NOT NULL)
          AND v.status = 'PERSPECTIVE_STATUS_PUBLISHED' AND v.deleted_at IS NULL AND v.hidden_at IS NULL
        LIMIT 100) x
) st
WHERE NOT EXISTS (
    SELECT 1 FROM up u JOIN places a ON a.id = u.ancestor_id
    WHERE u.place_id = m.id AND a.hidden_at IS NOT NULL)
ORDER BY m.under, m.is_exact DESC, m.is_prefix DESC, (st.stories > 0) DESC, m.level, m.len, m.lname, m.id
LIMIT $1::integer
`

type SearchPlacesParams struct {
	ResultLimit    int32
	Exact          string
	ParentIds      []uuid.UUID
	BroadFirst     bool
	Prefix         string
	Kind           pgtype.Text
	CandidateLimit int32
	Contains       string
}

type SearchPlacesRow struct {
	ID        uuid.UUID
	Kind      string
	Name      string
	ParentID  uuid.NullUUID
	Timezone  string
	Source    string
	UserAdded bool
	Category  string
	IsPrefix  bool
	Stories   int32
}

// Typeahead. Candidates are visible-by-row places whose lowercased name
// contains the pattern, restricted to the descendants of the parent_ids
// places when that is set (the request's parent, or the cities and towns a
// "starbucks tampa" search names, best first). Ranking: the place's first
// parent_ids entry above it, then exact name, then name prefix, then
// substring; within each, broader kinds first (STATE before STORE), then
// shorter names, then name and id. The top candidate_limit candidates are
// then checked for a hidden ancestor, and the first result_limit survivors
// returned.
//
// Every prefix match outranks every substring match, so the prefix matches
// are read first and the substring scan (the trigram index) runs only when
// they leave room: otherwise a common word such as "park" would rank
// 15,000 substring matches to keep 100. The prefix ranking reads only the name,
// kind and id, which places_name_rank_idx carries, so even "th" (21,000
// matches) is ranked from the index without a heap read; the remaining
// columns are read for the 100 candidates only. Under parent_ids, a prefix
// match under a later entry can fill the candidates before a substring
// match under an earlier one is read; the earlier entry still ranks first
// among what was read.
//
// broad_first reads the prefix matches in rank order a kind at a time
// instead of all at once: the exact names (an equality lookup), then the
// states and cities, then the towns (both through places_name_locality_idx,
// which also carries the path a parent filter reads), then the malls and
// stores, each only while the ones before leave fewer than
// candidate_limit. "a" matches 35,000 places and 264 states and cities, so
// it reads 265 rows instead of 35,000. Every exact name outranks every
// other prefix match and a broader kind a narrower one, so the candidates
// are the ones prefixed reads, provided the rank does not also turn on the
// parent (at most one parent_ids entry, whose descendants all rank under it
// alike) and there is no substring step. The caller sets broad_first only
// then: under three characters contains is the prefix itself, so that step
// could find nothing. With it set, prefixed and contained read no row;
// without it, the four steps read none.
// Readable stories at the place and below, counted up to 100: enough to
// tell friends which of several same-named entries everyone writes in.
// Within each match tier, places with stories first.
func (q *Queries) SearchPlaces(ctx context.Context, arg SearchPlacesParams) ([]SearchPlacesRow, error) {
	rows, err := q.db.Query(ctx, searchPlaces,
		arg.ResultLimit,
		arg.Exact,
		arg.ParentIds,
		arg.BroadFirst,
		arg.Prefix,
		arg.Kind,
		arg.CandidateLimit,
		arg.Contains,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchPlacesRow
	for rows.Next() {
		var i SearchPlacesRow
		if err := rows.Scan(
			&i.ID,
			&i.Kind,
			&i.Name,
			&i.ParentID,
			&i.Timezone,
			&i.Source,
			&i.UserAdded,
			&i.Category,
			&i.IsPrefix,
			&i.Stories,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

